 const retryer = require("../common/retryer");
 const calculateRank = require("../calculateRank");
-const { request, logger, CustomError } = require("../common/utils");
+const {
+  request,
+  logger,
+  CustomError,
+  MissingParamError,
+} = require("../common/utils");

 require("dotenv").config();

@@ -103,7 +108,7 @@ async function fetchStats(
   count_private = false,
   include_all_commits = false,
 ) {
-  if (!username) throw Error("Invalid username");
+  if (!username) throw new MissingParamError(["username"]);

   const stats = {
     name: "",
diff --git a/src/fetchers/top-languages-fetcher.js b/src/fetchers/top-languages-fetcher.js
index 555b454..9dd109e 100644
--- a/src/fetchers/top-languages-fetcher.js
+++ b/src/fetchers/top-languages-fetcher.js
@@ -1,5 +1,5 @@
 // @ts-check
-const { request, logger } = require("../common/utils");
+const { request, logger, MissingParamError } = require("../common/utils");
 const retryer = require("../common/retryer");
 require("dotenv").config();

@@ -45,7 +45,7 @@ const fetcher = (variables, token) => {
  * @returns {Promise<import("./types").TopLangData>}
  */
 async function fetchTopLanguages(username, exclude_repo = []) {
